list_managed_pages.beforeRequest:
var raw = inputs.limit;
var limit = raw === undefined || raw === null || String(raw).trim() === '' ? 25 : Number(raw);
request.query.limit = String(Math.min(100, Math.max(1, Math.floor(limit))));
var after = inputs.after == null ? '' : String(inputs.after).trim();
if (after) request.query.after = after; else delete request.query.after;
return request;
